class Solution {
public:
    bool isEscapePossible(vector<vector<int>>& blocked, vector<int>& source, vector<int>& target) {
        unordered_set<long long> blocked_set;
        for (auto& b : blocked) {
            blocked_set.insert((long long)b[0] * 1000000LL + b[1]);
        }

        return bfs(source, target, blocked_set) && bfs(target, source, blocked_set);
    }

private:
    bool bfs(const vector<int>& source, const vector<int>& target, unordered_set<long long>& blocked_set) {
        int dirs[4][2] = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
        unordered_set<long long> visited;
        queue<pair<int, int>> q;

        q.push({source[0], source[1]});
        visited.insert((long long)source[0] * 1000000LL + source[1]);

        while (!q.empty()) {
            auto curr = q.front();
            q.pop();

            if (curr.first == target[0] && curr.second == target[1]) {
                return true;
            }

            if (visited.size() > 20000) {
                return true;
            }

            for (int d = 0; d < 4; ++d) {
                int nx = curr.first + dirs[d][0];
                int ny = curr.second + dirs[d][1];

                if (nx >= 0 && nx < 1000000 && ny >= 0 && ny < 1000000) {
                    long long key = (long long)nx * 1000000LL + ny;
                    if (blocked_set.find(key) == blocked_set.end() && visited.find(key) == visited.end()) {
                        visited.insert(key);
                        q.push({nx, ny});
                    }
                }
            }
        }

        return false;
    }
};
